refentry.refsect1:
  &reftitle.examples;



    Пример восстановления предыдущего обработчика ошибок функцией restore_error_handler


     Пример определяет, вызвала ли ошибку функция
     unserialize, а затем восстанавливает исходный
     обработчик ошибок.



<?php

function unserialize_handler($errno, $errstr)
{
    echo "Недопустимое сериализованное значение.\n";
}

$serialized = 'foo';
set_error_handler('unserialize_handler');
$original = unserialize($serialized);
restore_error_handler();

?>


    &example.outputs;


Недопустимое сериализованное значение.
